import { cn } from "@/lib/utils";

export type IncidentStatus = "degraded" | "down";

export interface IncidentUpdate {
  time: string;
  label: string;
  note?: string;
}

export interface Incident {
  title: string;
  status: IncidentStatus;
  minutes: number;
  updates: IncidentUpdate[];
}

const STATUS_TEXT: Record<IncidentStatus, string> = {
  degraded: "Degraded",
  down: "Outage",
};

const STATUS_BADGE_CLASS: Record<IncidentStatus, string> = {
  degraded:
    "bg-amber-100 text-amber-800 dark:bg-amber-400/15 dark:text-amber-200",
  down: "bg-rose-100 text-rose-700 dark:bg-rose-500/15 dark:text-rose-300",
};

function IncidentUpdateItem({ update }: { update: IncidentUpdate }) {
  return (
    <li
      data-slot="incident-update"
      className="relative pb-2.5 pl-4 text-sm last:pb-0"
    >
      <span className="absolute top-[7px] -left-[3.5px] size-1.5 rounded-full bg-muted-foreground" />
      <span className="text-muted-foreground tabular-nums">{update.time}</span>{" "}
      <span className="font-medium">{update.label}</span>
      {update.note && (
        <span className="text-muted-foreground"> {update.note}</span>
      )}
    </li>
  );
}

function IncidentEntry({
  incident,
  className,
  ...props
}: React.ComponentProps<"div"> & { incident: Incident }) {
  return (
    <div
      data-slot="incident-entry"
      className={cn("mt-3", className)}
      {...props}
    >
      <p className="flex flex-wrap items-center gap-2 text-sm">
        <span
          className={cn(
            "rounded-full px-2 py-0.5 font-medium text-[11px]",
            STATUS_BADGE_CLASS[incident.status]
          )}
        >
          {STATUS_TEXT[incident.status]}
        </span>
        <span className="text-muted-foreground">
          {incident.title} · {incident.minutes} min
        </span>
      </p>
      <ol className="mt-2.5 ml-1 border-border border-l">
        {incident.updates.map((update) => (
          <IncidentUpdateItem
            key={`${update.time}-${update.label}`}
            update={update}
          />
        ))}
      </ol>
    </div>
  );
}

interface IncidentLogProps extends React.ComponentProps<"div"> {
  incidents: { service: string; incident: Incident }[];
  emptyMessage?: string;
}

function IncidentLog({
  incidents,
  emptyMessage = "No incidents recorded. Every service was operational.",
  className,
  ...props
}: IncidentLogProps) {
  return (
    <div data-slot="incident-log" className={cn(className)} {...props}>
      {incidents.length === 0 && (
        <p className="mt-1 text-sm text-muted-foreground">{emptyMessage}</p>
      )}
      {incidents.map(({ service, incident }) => (
        <div key={service}>
          <p className="text-sm font-medium">{service}</p>
          <IncidentEntry incident={incident} />
        </div>
      ))}
    </div>
  );
}

export { IncidentLog, IncidentEntry, IncidentUpdateItem };
